                comp.append((y, x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    edge = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if not edge:
                cavities.append(comp)
    # Recolor the boundary layer inside cavities; the deeper core remains 0.
    cavity_boundary = set()
